<?php

declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';

use EventMenu\Core\Database;
use EventMenu\Core\Security;
use EventMenu\Services\CheckoutService;

$pdo=Database::connection();$token=trim((string)($_GET['t']??''));$error=null;
function p_money(int$c):string{return'R$ '.number_format($c/100,2,',','.');}
function allowed_checkout_url(string$provider,string$url):bool{$p=parse_url($url);if(($p['scheme']??'')!=='https'||empty($p['host']))return false;$h=strtolower($p['host']);$allowed=['stripe'=>['stripe.com'],'mercadopago'=>['mercadopago.com','mercadopago.com.br'],'pagbank'=>['pagseguro.uol.com.br','pagbank.com.br']];foreach($allowed[$provider]??[]as$suffix){if($h===$suffix||str_ends_with($h,'.'.$suffix))return true;}return false;}
function public_order_status(string$status):string{return match($status){'pending'=>'Aguardando confirmação','confirmed'=>'Confirmado','preparing'=>'Em preparo','ready'=>'Pronto','out_for_delivery'=>'Saiu para entrega','completed'=>'Concluído','cancelled'=>'Cancelado',default=>$status};}
function public_channel(string$channel):string{return match($channel){'delivery'=>'Delivery','pickup'=>'Retirada no local','table'=>'Mesa','counter'=>'Balcão','event'=>'Evento',default=>$channel};}
function public_schedule(?string$utc,array$settings):?string{if(!$utc)return null;try{$tz=new DateTimeZone((string)($settings['timezone']??'America/Sao_Paulo'));return(new DateTimeImmutable($utc,new DateTimeZone('UTC')))->setTimezone($tz)->format('d/m/Y \à\s H:i');}catch(Throwable){return null;}}
function provider_label(string$p):string{return match($p){'stripe'=>'Stripe','mercadopago'=>'Mercado Pago','pagbank'=>'PagBank',default=>ucfirst($p)};}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Security::validateCsrf($_POST['_csrf']??null))$error='Sessão expirada.';else try{$provider=(string)($_POST['provider']??'');$checkout=(new CheckoutService())->create($token,$provider);if(!allowed_checkout_url($checkout['provider'],$checkout['url']))throw new RuntimeException('URL de checkout rejeitada por segurança.');header('Location: '.$checkout['url'],true,303);exit;}catch(Throwable$e){$error=$e->getMessage();}}
$s=$pdo->prepare('SELECT o.*,t.name tenant_name,t.slug tenant_slug,t.primary_color,t.secondary_color,t.settings tenant_settings,c.name customer_name,dz.name delivery_zone_name FROM orders o JOIN tenants t ON t.id=o.tenant_id LEFT JOIN customers c ON c.id=o.customer_id LEFT JOIN delivery_zones dz ON dz.id=o.delivery_zone_id WHERE o.public_token=? AND t.status="active" LIMIT 1');$s->execute([$token]);$order=$s->fetch();if(!$order){http_response_code(404);exit('Pedido não encontrado.');}
$settings=json_decode((string)($order['tenant_settings']??'{}'),true);if(!is_array($settings))$settings=[];$scheduledLabel=public_schedule($order['scheduled_for']??null,$settings);$items=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$items->execute([$order['id']]);$items=$items->fetchAll();$g=$pdo->prepare('SELECT provider FROM payment_gateways WHERE tenant_id=? AND active=1 ORDER BY provider');$g->execute([$order['tenant_id']]);$gateways=$g->fetchAll(PDO::FETCH_COLUMN);$tickets=$pdo->prepare('SELECT t.*,e.name event_name,b.name batch_name FROM tickets t JOIN events e ON e.id=t.event_id JOIN ticket_batches b ON b.id=t.batch_id WHERE t.order_id=? ORDER BY t.id');$tickets->execute([$order['id']]);$tickets=$tickets->fetchAll();$canPay=in_array($order['payment_status'],['unpaid','pending','failed'],true)&&!in_array($order['status'],['cancelled','completed'],true);$paid=$order['payment_status']==='paid';$primary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($order['primary_color']??''))?(string)$order['primary_color']:'#6d4aff';$secondary=preg_match('/^#[0-9a-fA-F]{6}$/',(string)($order['secondary_color']??''))?(string)$order['secondary_color']:'#8b5cf6';$eventOrder=$order['channel']==='event';
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="<?= Security::e($primary) ?>"><title>Pedido #<?= (int)$order['id'] ?> — EventMenu</title><link rel="stylesheet" href="<?= Security::e(app_url('/assets/app.css')) ?>?v=92legacy-checkout"><style>:root{--checkout:<?= Security::e($primary) ?>;--checkout2:<?= Security::e($secondary) ?>}.legacy-checkout-page{margin:0;background:#f5f4f8;color:#20202b;font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.checkout-top{height:66px;background:#17121f;color:#fff;display:flex;align-items:center}.checkout-top-inner{width:min(1060px,100%);margin:auto;padding:0 18px;display:flex;justify-content:space-between;align-items:center}.checkout-brand{font-weight:950}.checkout-brand span{color:#9c84ff}.checkout-shell{width:min(980px,calc(100% - 24px));margin:28px auto 70px}.checkout-stepper{display:grid;grid-template-columns:repeat(<?= $eventOrder?'4':'3' ?>,1fr);gap:5px;margin-bottom:21px}.checkout-step{text-align:center;color:#96919e;font-size:10px;font-weight:800}.checkout-step b{display:grid;place-items:center;width:31px;height:31px;margin:0 auto 6px;border-radius:50%;background:#e7e4ed;color:#77717e}.checkout-step.done b,.checkout-step.active b{background:var(--checkout);color:#fff}.checkout-step.active{color:#5d49ad}.checkout-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(300px,.8fr);gap:16px}.checkout-card{background:#fff;border:1px solid #e7e4ec;border-radius:18px;padding:21px;box-shadow:0 8px 30px #31263f0d}.checkout-card h1,.checkout-card h2{margin-top:0}.checkout-summary-line{display:flex;justify-content:space-between;gap:12px;padding:11px 0;border-bottom:1px solid #efedf2}.checkout-summary-line small{display:block;color:#8b8794;margin-top:3px}.checkout-totals{margin-top:13px}.checkout-total-row{display:flex;justify-content:space-between;padding:6px 0;color:#747180}.checkout-total-row.total{font-size:21px;color:#24212b;font-weight:950;padding-top:13px}.checkout-total-row.total strong{color:var(--checkout)}.checkout-info-box{border:1px solid #ebe8ef;border-radius:13px;padding:13px;margin-bottom:12px}.checkout-info-box span{display:block;color:#8b8794;font-size:10px;text-transform:uppercase;font-weight:850;letter-spacing:.08em;margin-bottom:5px}.payment-options{display:grid;gap:9px;margin-top:14px}.payment-option{border:1px solid #e6e2eb;border-radius:14px;padding:14px;display:grid;grid-template-columns:1fr auto;align-items:center;gap:10px}.payment-option strong{display:block}.payment-option small{color:#86828f}.payment-option button{background:var(--checkout);color:#fff;border:0;border-radius:11px;min-height:42px;font-weight:850}.confirmation{border:1px solid #cdeedc;background:#ebf9f2;color:#147a52;border-radius:14px;padding:15px;margin-bottom:16px}.ticket-list{display:grid;gap:9px}.ticket-entry{display:flex;justify-content:space-between;gap:10px;align-items:center;border:1px solid #e7e4ec;border-radius:13px;padding:12px}.ticket-entry a{background:#f0edff;color:#6249d6;border-radius:10px;padding:9px 11px;font-weight:800;font-size:11px}.checkout-security{font-size:10px;color:#96929e;line-height:1.5;margin-top:13px}@media(max-width:760px){.checkout-grid{grid-template-columns:1fr}.checkout-shell{width:calc(100% - 18px);margin-top:18px}.checkout-card{padding:15px}.payment-option{grid-template-columns:1fr}.payment-option button{width:100%}.checkout-step{font-size:8px}.ticket-entry{align-items:flex-start;flex-direction:column}.ticket-entry a{width:100%;text-align:center}}</style></head><body class="legacy-checkout-page"><header class="checkout-top"><div class="checkout-top-inner"><div class="checkout-brand">EVENTMENU <span>PREMIUM</span></div><span><?= Security::e($order['tenant_name']) ?></span></div></header><main class="checkout-shell"><div class="checkout-stepper"><?php if($eventOrder):?><div class="checkout-step done"><b>1</b>Ingressos</div><div class="checkout-step done"><b>2</b>Dados</div><div class="checkout-step <?= $paid?'done':'active' ?>"><b>3</b>Pagamento</div><div class="checkout-step <?= $paid?'active':'' ?>"><b>4</b>Confirmação</div><?php else:?><div class="checkout-step done"><b>1</b><?= $order['channel']==='pickup'?'Retirada':'Entrega' ?></div><div class="checkout-step <?= $paid?'done':'active' ?>"><b>2</b>Pagamento</div><div class="checkout-step <?= $paid?'active':'' ?>"><b>3</b>Confirmação</div><?php endif;?></div><?php if($error):?><div class="alert error"><?= Security::e($error) ?></div><?php endif;?><div class="checkout-grid"><section class="checkout-card"><h1><?= $paid?'Pedido confirmado':'Finalizar Pedido' ?></h1><p class="muted">Pedido #<?= (int)$order['id'] ?> · <?= Security::e(public_channel((string)$order['channel'])) ?></p><?php if($paid):?><div class="confirmation"><strong>Pagamento confirmado pelo servidor.</strong><br>Seu pedido está registrado e seguirá o fluxo da operação.</div><?php endif;?><?php foreach($items as$item):?><div class="checkout-summary-line"><span><?= Security::e($item['name_snapshot']) ?><small><?= Security::e((string)$item['quantity']) ?> × <?= p_money((int)$item['unit_price_cents']) ?></small></span><strong><?= p_money((int)$item['total_cents']) ?></strong></div><?php endforeach;?><div class="checkout-totals"><div class="checkout-total-row"><span>Subtotal</span><span><?= p_money((int)$order['subtotal_cents']) ?></span></div><?php if((int)$order['discount_cents']>0):?><div class="checkout-total-row"><span>Desconto</span><span>- <?= p_money((int)$order['discount_cents']) ?></span></div><?php endif;?><?php if($order['channel']==='delivery'):?><div class="checkout-total-row"><span>Taxa de Entrega</span><span><?= p_money((int)$order['delivery_fee_cents']) ?></span></div><?php endif;?><div class="checkout-total-row total"><span>Total</span><strong><?= p_money((int)$order['total_cents']) ?></strong></div></div><?php if($paid&&$tickets):?><h2 style="margin-top:24px">Seus ingressos</h2><div class="ticket-list"><?php foreach($tickets as$t):?><div class="ticket-entry"><div><strong><?= Security::e($t['batch_name']) ?></strong><small class="muted" style="display:block"><?= Security::e($t['code']) ?></small></div><a href="<?= Security::e(app_url('/ingresso.php?t='.urlencode($t['qr_token']))) ?>">Abrir ingresso / QR</a></div><?php endforeach;?></div><?php endif;?></section><aside class="checkout-card"><?php if($scheduledLabel):?><div class="checkout-info-box"><span>Agendado para</span><strong><?= Security::e($scheduledLabel) ?></strong></div><?php endif;?><?php if($order['channel']==='delivery'):?><div class="checkout-info-box"><span>Endereço de Entrega</span><strong><?= Security::e($order['delivery_address']??'') ?></strong><div class="muted"><?= Security::e(trim(($order['delivery_neighborhood']??'').' · '.($order['delivery_city']??''),' ·')) ?></div></div><div class="checkout-info-box"><span>Prazo estimado</span><strong><?= (int)($order['delivery_eta_min_minutes']??30) ?>–<?= (int)($order['delivery_eta_max_minutes']??60) ?> min</strong></div><?php elseif($order['channel']==='pickup'):?><div class="checkout-info-box"><span>Recebimento</span><strong>Retirada no local</strong></div><?php elseif($eventOrder):?><div class="checkout-info-box"><span>Titular</span><strong><?= Security::e($order['customer_name']??'Cliente') ?></strong></div><?php endif;?><?php if(!$paid&&$canPay):?><h2>Forma de Pagamento</h2><?php if($gateways):?><div class="payment-options"><?php foreach($gateways as$provider):?><div class="payment-option"><div><strong><?= Security::e(provider_label((string)$provider)) ?></strong><small>Pix e/ou cartão conforme configuração do provedor.</small></div><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="provider" value="<?= Security::e($provider) ?>"><button>Pagar</button></form></div><?php endforeach;?></div><p class="checkout-security">A compra só é confirmada depois que o servidor valida o pagamento diretamente com o provedor. O retorno do navegador não confirma pagamento sozinho.</p><?php else:?><div class="alert">Nenhum pagamento online foi habilitado por esta empresa.</div><?php endif;?><?php elseif(!$paid):?><div class="alert">Status: <?= Security::e(public_order_status((string)$order['status'])) ?> · pagamento <?= Security::e((string)$order['payment_status']) ?>.</div><?php endif;?></aside></div></main></body></html>
